-- Approved F rules, installed only by migration028 and gated to saved v17.
-- Damage prevention is resolved by the existing authority before this helper.
-- Zero maximum means permanent elimination; positive maxima retain revival.
create or replace function ml_private.p3f_jelly_health(hp numeric,max_hp numeric,amount numeric) returns jsonb language plpgsql immutable set search_path=pg_catalog,ml_private as $$declare after_hp numeric;after_max numeric;begin
 perform ml_private.need(hp is not null and max_hp is not null and amount is not null and hp=trunc(hp) and max_hp=trunc(max_hp) and amount=trunc(amount) and hp>=0 and max_hp>=hp and amount>=0 and hp<=9007199254740991 and max_hp<=9007199254740991 and amount<=9007199254740991,'水母真伤生命输入无效');
 after_max:=greatest(0,max_hp-amount);after_hp:=case when after_max=0 then 0 else greatest(0,hp-amount) end;
 return jsonb_build_object('hp',after_hp,'maxHp',after_max,'hpLoss',hp-after_hp,'maxHpLoss',max_hp-after_max,'dead',after_hp=0 or after_max=0);end $$;

create or replace function ml_private.p3f_enabled(s jsonb) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select s->>'version'='web-v0.1.17'$$;
create or replace function ml_private.p3f_uncapped(s jsonb,a integer) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select ml_private.p3f_enabled(s) and s#>>array['players',a::text,'character']='character-019'$$;
create or replace function ml_private.p3f_valid(s jsonb) returns boolean language plpgsql immutable set search_path=pg_catalog,ml_private as $$declare f jsonb:=s#>'{stage3,f}';k text;v jsonb;begin
 if not ml_private.p3f_enabled(s) then return true;end if;
 if coalesce(jsonb_typeof(f->'firstDeath'),'null')<>'boolean' or coalesce(jsonb_typeof(f->'hitSerial'),'null')<>'number' or (f->>'hitSerial')::numeric<>trunc((f->>'hitSerial')::numeric) or (f->>'hitSerial')::numeric not between 0 and 9007199254740991 then return false;end if;
 foreach k in array array['wounds','unlimitedCeil','home','executeUsed'] loop
  if coalesce(jsonb_typeof(f->k),'null')<>'array' or jsonb_array_length(f->k)<>4 then return false;end if;
  for v in select * from ml_private.arr(f->k) loop
   if k in ('home','executeUsed') then if jsonb_typeof(v)<>'boolean' then return false;end if;
   elsif not(k='unlimitedCeil' and v='null'::jsonb) then if jsonb_typeof(v)<>'number' then return false;end if;if (v#>>'{}')::numeric<>trunc((v#>>'{}')::numeric) or (v#>>'{}')::numeric not between 0 and 9007199254740991 then return false;end if;end if;
  end loop;
 end loop;
 foreach k in array array['dry','entered','results'] loop if coalesce(jsonb_typeof(f->k),'null')<>'object' then return false;end if;if k<>'results' and exists(select 1 from jsonb_each(f->k) q where jsonb_typeof(q.value)<>'boolean') then return false;end if;end loop;return true;end $$;
create or replace function ml_private.p3f_start(s jsonb,a integer) returns jsonb language plpgsql immutable set search_path=pg_catalog,ml_private as $$declare f jsonb;begin
 if not ml_private.p3f_enabled(s) then return s;end if;
 f:=coalesce(s#>'{stage3,f}',jsonb_build_object('firstDeath',false,'wounds','[0,0,0,0]'::jsonb,'unlimitedCeil','[null,null,null,null]'::jsonb,'home','[false,false,false,false]'::jsonb,'executeUsed','[false,false,false,false]'::jsonb,'dry','{}'::jsonb,'entered','{}'::jsonb,'hitSerial',0,'results','{}'::jsonb));
 f:=f||jsonb_build_object('home','[false,false,false,false]'::jsonb,'dry','{}'::jsonb,'entered','{}'::jsonb,'results','{}'::jsonb);f:=jsonb_set(f,array['executeUsed',a::text],'false');return jsonb_set(s,'{stage3,f}',f);end $$;
create or replace function ml_private.p3f_healing(s jsonb,a integer,amount integer,food boolean) returns integer language plpgsql stable set search_path=pg_catalog,ml_private as $$declare p jsonb:=s->'players'->a;cap integer;fulln boolean:=ml_private.stage3_equipped(s,a,'basic-072');begin
 if (p->>'hp')::int<=0 or amount<=0 or food and p->>'character'='character-027' then return 0;end if;
 if ml_private.p3f_uncapped(s,a) then cap:=coalesce((s#>>array['stage3','f','unlimitedCeil',a::text])::int,2147483647);return greatest(0,least(case when fulln then 2 else amount end,cap-(p->>'hp')::int));end if;
 cap:=greatest(0,(p->>'maxHp')::int-(s#>>array['stage3','f','wounds',a::text])::int);return greatest(0,least(case when fulln then cap-(p->>'hp')::int else amount end,cap-(p->>'hp')::int));end $$;
create or replace function ml_private.p3f_cast_heal(s jsonb,a integer,definition text) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare amount integer;begin
 if not ml_private.p3f_uncapped(s,a) or not(coalesce(ml_private.version_catalog(s->>'version')#>array['runtimeData','cardTags',definition],'[]') ? '搏击操') then return s;end if;
 amount:=ml_private.stage3_healing(s,a,1,false);s:=jsonb_set(s,array['players',a::text,'hp'],to_jsonb((s#>>array['players',a::text,'hp'])::int+amount));return ml_private.emit(s,'heal','S'||(a+1)||' 搏击操爱好者回复'||amount||'生命');end $$;
create or replace function ml_private.p3f_can_move(s jsonb,a integer) returns boolean language sql stable set search_path=pg_catalog,ml_private as $$select not ml_private.p3f_enabled(s) or s#>>array['players',a::text,'character']<>'character-007' or ml_private.stage3_equipped(s,a,'basic-069')$$;
create or replace function ml_private.p3f_preview_move(s jsonb,a integer,destination text) returns boolean language plpgsql stable set search_path=pg_catalog,ml_private as $$begin
 if not ml_private.p3f_enabled(s) then return true;end if;if not ml_private.p3f_can_move(s,a) then return false;end if;
 return s#>>array['players',a::text,'character']<>'character-036' or not ml_private.stage4_board_water(s,s#>>array['players',a::text,'cell'],a) or ml_private.stage4_board_water(s,destination,a) or coalesce(s#>>array['stage3','f','dry',ml_private.p3e_root(s)||':'||a],'true')<>'false';end $$;
create or replace function ml_private.p3f_move_gate(s jsonb,a integer,destination text,placement boolean default false,root text default null) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare k text;allowed boolean;begin
 if not ml_private.p3f_enabled(s) or placement then return s||jsonb_build_object('_fMoveAllowed',true);end if;
 if not ml_private.p3f_can_move(s,a) then return s||jsonb_build_object('_fMoveAllowed',false);end if;
 if s#>>array['players',a::text,'character']<>'character-036' or not ml_private.stage4_board_water(s,s#>>array['players',a::text,'cell'],a) or ml_private.stage4_board_water(s,destination,a) then return s||jsonb_build_object('_fMoveAllowed',true);end if;
 k:=coalesce(root,ml_private.p3e_root(s))||':'||a;allowed:=(s#>>array['stage3','f','dry',k])::boolean;
 if allowed is null then if s->>'_eProbe'='true' then allowed:=true;else s:=ml_private.die(s,'干枯');allowed:=(s->>'_roll')::int=6;s:=s-'_roll';end if;s:=jsonb_set(s,array['stage3','f','dry',k],to_jsonb(allowed));end if;return s||jsonb_build_object('_fMoveAllowed',allowed);end $$;
create or replace function ml_private.p3f_modifiers(s jsonb,h jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare a integer:=(h->>'target')::int;src integer:=(h->>'source')::int;c jsonb:=s#>'{cardStack,stack,-1}';origin text;begin
 if not ml_private.p3f_enabled(s) then return h;end if;
 if s#>>array['players',a::text,'character']='character-018' and s#>>array['stage3','f','home',a::text]='true' then return null;end if;
 if src is not null and s#>>array['players',src::text,'character']='character-036' then if not ml_private.character_effect_allowed(jsonb_build_object('origin','role-locked','actor',src,'roleModifiers','[]'::jsonb),a,s#>>array['players',a::text,'character']) then return null;end if;h:=h||jsonb_build_object('trueDamage',true,'jelly',true);end if;
 origin:=coalesce(h->>'originCard',case when (c->>'actor')::int=src and h->>'category'='attack' and coalesce(h->>'extra','false')<>'true' and coalesce(h->>'reflected','false')<>'true' then c->>'definition' end);
 if s#>>array['players',a::text,'character']='character-018' and origin is not null and coalesce(ml_private.version_catalog(s->>'version')#>array['runtimeData','cardTags',origin],'[]') ? '帝汶' then h:=h||jsonb_build_object('amount',(h->>'amount')::int+1);end if;return h;end $$;
create or replace function ml_private.p3f_damage(s jsonb,hits jsonb,environment boolean,skip_pursuit boolean) returns jsonb language plpgsql immutable set search_path=pg_catalog,ml_private as $$declare token integer:=(s#>>'{stage3,f,hitSerial}')::int+1;begin
 s:=jsonb_set(s,'{stage3,f,hitSerial}',to_jsonb(token));return s||jsonb_build_object('_triggers',jsonb_build_array(ml_private.stage3_task('f-damage',jsonb_build_object('data',jsonb_build_object('hits',hits,'environment',environment,'suppressPursuit',skip_pursuit,'token',token,'index',0,'injured','[]'::jsonb)))));end $$;
create or replace function ml_private.p3f_damage_frame(s jsonb,d jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare idx integer:=(d->>'index')::int;h jsonb;original jsonb;p jsonb;result jsonb;src integer;a integer;blocked integer;remaining integer;loss integer;prior integer;wound integer;environment boolean:=(d->>'environment')::boolean;begin
 if not(d ? 'batch') then s:=jsonb_set(s,'{batch}',to_jsonb((s->>'batch')::int+1));d:=d||jsonb_build_object('batch',s->'batch');end if;
 while idx<jsonb_array_length(d->'hits') loop
  original:=d->'hits'->idx;a:=(original->>'target')::int;if not ml_private.stage4_on_board(s,a) or (original->>'amount')::int<=0 then idx:=idx+1;continue;end if;
  if d ? 'prepared' then h:=d#>'{prepared,hit}';blocked:=(d#>>'{prepared,blocked}')::int;remaining:=(d#>>'{prepared,remaining}')::int;d:=d-'prepared';
  else
   s:=ml_private.stage4_prepare_hit(s,original,environment);h:=s->'_hit';s:=s-'_hit';if h='null'::jsonb then idx:=idx+1;continue;end if;
   if not environment and s#>>array['players',a::text,'character']='character-037' or ml_private.stage3_equipped(s,a,'basic-059') then h:=h||jsonb_build_object('amount',least(1,(h->>'amount')::int));end if;
   if (h->>'amount')::int<=0 then idx:=idx+1;continue;end if;p:=s->'players'->a;blocked:=case when h->>'trueDamage'='true' then 0 else least((p->>'shield')::int,(h->>'amount')::int) end;remaining:=(h->>'amount')::int-blocked;s:=jsonb_set(s,array['players',a::text,'shield'],to_jsonb((p->>'shield')::int-blocked));
   if p->>'character'='character-051' and remaining>0 and (p->>'maxHp')::int>1 then d:=d||jsonb_build_object('index',idx,'prepared',jsonb_build_object('hit',h,'blocked',blocked,'remaining',remaining));return ml_private.select_choice(s,'f-tenacity',a,at,jsonb_build_object('count',least(remaining,(p->>'hp')::int,(p->>'maxHp')::int-1),'data',d));end if;
  end if;
  p:=s->'players'->a;prior:=(p->>'hp')::int;
  if h->>'jelly'='true' and not ml_private.p3f_uncapped(s,a) then result:=ml_private.p3f_jelly_health(prior,(p->>'maxHp')::int,remaining);p:=p||jsonb_build_object('hp',result->'hp','maxHp',result->'maxHp');loss:=(result->>'hpLoss')::int;else loss:=least(prior,remaining);p:=p||jsonb_build_object('hp',prior-loss);end if;s:=ml_private.put_player(s,a,p);src:=(h->>'source')::int;
  if src is not null and ml_private.enemy(s,src,a) then s:=ml_private.put_player(s,src,(s->'players'->src)||jsonb_build_object('damage',(s#>>array['players',src::text,'damage'])::int+loss,'kills',(s#>>array['players',src::text,'kills'])::int+case when (p->>'hp')::int=0 and loss>0 then 1 else 0 end));end if;
  s:=ml_private.emit(s,'damage','S'||(a+1)||' '||case when environment then '环境' else '普通' end||'伤害'||(h->>'amount')||'，护盾抵挡'||blocked||'，实际失血'||loss,h||jsonb_build_object('blocked',blocked,'loss',loss,'batch',d->'batch'));
  if loss>0 then
   d:=jsonb_set(d,'{injured}',(d->'injured')||jsonb_build_array(h||jsonb_build_object('loss',loss)));
   if s#>>'{stage3,f,firstDeath}'='false' and src is not null and s#>>array['players',src::text,'character']='character-017' then wound:=(s#>>array['stage3','f','wounds',a::text])::int+loss;s:=jsonb_set(s,array['stage3','f','wounds',a::text],to_jsonb(wound));if ml_private.p3f_uncapped(s,a) then s:=jsonb_set(s,array['stage3','f','unlimitedCeil',a::text],to_jsonb(least(coalesce((s#>>array['stage3','f','unlimitedCeil',a::text])::int,prior),prior)-loss));end if;end if;
   if (p->>'hp')::int>0 and p->>'character'='character-018' then s:=jsonb_set(s,array['stage3','f','home',a::text],'true');end if;
   if (p->>'hp')::int>0 and p->>'character'='character-032' then s:=jsonb_set(s,array['players',a::text,'maxHp'],to_jsonb((p->>'maxHp')::int+loss));s:=ml_private.stage3_gain_ap(s,a,2*loss)-'_gain';s:=ml_private.emit(s,'skill','S'||(a+1)||' 和气：上限+'||loss||'，获得'||(2*loss)||'AP');end if;
  end if;idx:=idx+1;
 end loop;
 if s#>>'{cardStack,stack,-1,definition}'='basic-006' then s:=jsonb_set(s,array['stage3','f','results',d->>'token'],d->'injured');end if;
 s:=ml_private.p3f_complete_damage(s,d->'injured',environment,(d->>'suppressPursuit')::boolean);return ml_private.stage3_prepend(s,s->'_triggers')-'_triggers';end $$;

create or replace function ml_private.p3f_allowed(s jsonb,a integer,target integer,groupn boolean default false) returns boolean language sql stable set search_path=pg_catalog,ml_private as $$select ml_private.stage4_on_board(s,target) and (not groupn or not(s#>>array['players',target::text,'character']='character-027' and jsonb_array_length(s#>array['players',target::text,'hand'])=1)) and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',a,'roleModifiers','[]'::jsonb),target,s#>>array['players',target::text,'character'])$$;
create or replace function ml_private.p3f_targets(s jsonb,a integer,execute_n boolean default false) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select coalesce(jsonb_agg(v order by n),'[]') from jsonb_array_elements(s->'order') with ordinality q(v,n) where (v#>>'{}')::int<>a and ml_private.p3f_allowed(s,a,(v#>>'{}')::int) and (not execute_n or (s#>>array['players',v#>>'{}','hp'])::int<=2 and ml_private.game_data(s,'map')#>>array[s#>>array['players',v#>>'{}','cell'],'region']=ml_private.game_data(s,'map')#>>array[s#>>array['players',a::text,'cell'],'region'])$$;
create or replace function ml_private.p3f_arrival(s jsonb,mover integer,origin text,destination text) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare region text:=ml_private.game_data(s,'map')#>>array[destination,'region'];root text;tasks jsonb:='[]';a integer;action text;k text;begin
 if not ml_private.p3f_enabled(s) or origin=destination then return s||jsonb_build_object('_fArrival','[]'::jsonb);end if;root:=ml_private.p3e_root(s);
 for a in select (v#>>'{}')::int from ml_private.arr(s->'order') v loop
  if a=mover or not ml_private.stage4_on_board(s,a) or ml_private.game_data(s,'map')#>>array[s#>>array['players',a::text,'cell'],'region']<>region then continue;end if;
  action:=case when s#>>array['players',a::text,'character']='character-032' and ml_private.game_data(s,'map')#>>array[origin,'region']<>region then 'f-bccb' when s#>>array['players',a::text,'character']='character-036' then 'f-sting' end;if action is null then continue;end if;k:=root||':'||a||':'||mover;if s#>>array['stage3','f','entered',k]='true' then continue;end if;
  s:=jsonb_set(s,array['stage3','f','entered',k],'true');tasks:=tasks||jsonb_build_array(ml_private.stage3_task(action,jsonb_build_object('actor',a,'target',mover,'data',jsonb_build_object('region',region,'root',root))));
 end loop;return s||jsonb_build_object('_fArrival',tasks);end $$;
create or replace function ml_private.p3f_end_tasks(s jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare a integer:=(s->>'active')::int;owner integer;tasks jsonb:='[]';region text:=ml_private.game_data(s,'map')#>>array[s#>>array['players',a::text,'cell'],'region'];begin
 if not ml_private.p3f_enabled(s) or not ml_private.stage4_on_board(s,a) then return tasks;end if;
 for owner in select (v#>>'{}')::int from ml_private.arr(s->'order') v where (v#>>'{}')::int<>a loop if ml_private.stage4_on_board(s,owner) and s#>>array['players',owner::text,'character']='character-036' and ml_private.game_data(s,'map')#>>array[s#>>array['players',owner::text,'cell'],'region']=region then tasks:=tasks||jsonb_build_array(ml_private.stage3_task('f-sting',jsonb_build_object('actor',owner,'target',a,'data',jsonb_build_object('root','end'||(s#>>'{stage3,turn}'),'region',region))));end if;end loop;return tasks;end $$;
create or replace function ml_private.p3f_arrival_order(s jsonb,a integer,origin text,cell text,reactive boolean) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select case when ml_private.game_data(s,'map')#>>array[origin,'region'] is distinct from ml_private.game_data(s,'map')#>>array[cell,'region'] and ml_private.stage4_desert(s,a) is not null then jsonb_build_array(ml_private.stage3_task('board-desert',jsonb_build_object('actor',a))) else '[]'::jsonb end||coalesce(s->'_fArrival','[]')||case when reactive then ml_private.stage4_reactive_arrival(s,a,origin,cell) else '[]'::jsonb end$$;
create or replace function ml_private.p3f_card_targets(s jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare c jsonb:=s#>'{cardStack,stack,-1}';a integer;actor integer:=(c->>'actor')::int;tasks jsonb:='[]';begin
 if not ml_private.p3f_enabled(s) or c->>'fTargetsDone'='true' then return s||jsonb_build_object('_fTargets',tasks);end if;
 s:=jsonb_set(s,array['cardStack','stack',(jsonb_array_length(s#>'{cardStack,stack}')-1)::text,'fTargetsDone'],'true');
 if s->>'mode'<>'team' or c->>'countered'='true' or c->'responseTo'<>'null'::jsonb then return s||jsonb_build_object('_fTargets',tasks);end if;
 for a in select (v#>>'{}')::int from ml_private.arr(s->'order') v loop
  if a<>actor and ml_private.stage4_on_board(s,a) and s#>>array['players',a::text,'character']='character-017' and s#>array['players',a::text,'team']=s#>array['players',actor::text,'team'] and c->'targets' @> jsonb_build_array(a) and not(c->'cancelled' @> jsonb_build_array(a)) and ml_private.stage3_card_allowed(s,a,c->>'definition',c->'effect') then tasks:=tasks||jsonb_build_array(ml_private.stage3_task('f-self-harm',jsonb_build_object('actor',a,'serial',c->'serial')));end if;
 end loop;return s||jsonb_build_object('_fTargets',tasks);end $$;
create or replace function ml_private.p3f_skill(s jsonb,cmd jsonb) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer:=(cmd->>'actor')::int;k text:=cmd->>'kind';p jsonb:=s->'players'->a;target integer:=(cmd->>'target')::int;card text:=cmd->>'card';hits jsonb;region text;begin
 perform ml_private.need(ml_private.p3f_enabled(s) and ml_private.stage4_on_board(s,a) and p->>'character'=case when k='execute' then 'character-007' else 'character-052' end,'本角色不能发动此技能');
 if k='magma' then perform ml_private.need((p->>'ap')::int>=2,'岩浆之力需要2AP');s:=jsonb_set(s,array['players',a::text,'ap'],to_jsonb((p->>'ap')::int-2));region:=ml_private.game_data(s,'map')#>>array[p->>'cell','region'];
  select coalesce(jsonb_agg(jsonb_build_object('target',v,'amount',1,'source',a,'category','response') order by n),'[]') into hits from jsonb_array_elements(s->'order') with ordinality q(v,n) where (v#>>'{}')::int<>a and ml_private.p3f_allowed(s,a,(v#>>'{}')::int,true) and ml_private.game_data(s,'map')#>>array[s#>>array['players',v#>>'{}','cell'],'region']=region;
  s:=ml_private.damage(s,hits);s:=jsonb_set(s,'{queue}',(s->'queue')||(s->'_triggers')||jsonb_build_array(ml_private.stage3_task('f-boundary','{}')))-'_triggers';return ml_private.emit(s,'skill','S'||(a+1)||' 岩浆之力，支付2AP');end if;
 perform ml_private.need(s#>>array['stage3','f','executeUsed',a::text]='false' and card is not null and p->'hand' ? card and target is not null and ml_private.p3f_targets(s,a,true) @> jsonb_build_array(target),'斩杀次数、手牌或目标不合法');s:=jsonb_set(s,array['stage3','f','executeUsed',a::text],'true');s:=jsonb_set(s,array['players',a::text,'hand'],(p->'hand')-card);s:=ml_private.exercise_discard(s,jsonb_build_array(card));s:=ml_private.die(s,'斩杀');
 if (s->>'_roll')::int%2=1 then s:=s-'_roll';s:=jsonb_set(s,'{batch}',to_jsonb((s->>'batch')::int+1));s:=jsonb_set(s,array['players',target::text,'hp'],'0');s:=jsonb_set(s,array['stage3','f','wounds',target::text],'0');s:=jsonb_set(s,array['stage3','f','unlimitedCeil',target::text],'null');if ml_private.enemy(s,a,target) then s:=jsonb_set(s,array['players',a::text,'kills'],to_jsonb((s#>>array['players',a::text,'kills'])::int+1));end if;
  s:=ml_private.p3f_complete_damage(s,'[]',false,false);s:=jsonb_set(s,array['stage3','deathTurns',target::text],'-1');s:=jsonb_set(s,'{queue}',(s->'queue')||(s->'_triggers'))-'_triggers';s:=ml_private.emit(s,'skill','S'||(a+1)||' 斩杀：S'||(target+1)||' 直接淘汰，不能普通复活');else s:=ml_private.emit(s-'_roll','skill','S'||(a+1)||' 斩杀偶数，无效果');end if;
 return jsonb_set(s,'{queue}',(s->'queue')||jsonb_build_array(ml_private.stage3_task('f-boundary','{}')));end $$;
create or replace function ml_private.p3f_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare action text:=t->>'action';a integer:=coalesce((t->>'actor')::int,(s->>'active')::int);target integer:=(t->>'target')::int;data jsonb:=t->'data';c jsonb:=s#>'{cardStack,stack,-1}';cells jsonb;cell text;amount integer;region text;begin
 if action='f-damage' then return ml_private.p3f_damage_frame(s,data,at);end if;
 if action='f-card-resume' then return ml_private.stage3_handle_task_before_stage4(s,t||jsonb_build_object('action','continue'),at);end if;
 if action='f-boundary' then s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' and not ml_private.stage4_on_board(s,(s->>'active')::int) then s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','next')));end if;return s;end if;
 if action='f-vampire' then select coalesce(sum((h->>'loss')::int),0) into amount from ml_private.arr(coalesce(s#>array['stage3','f','results',data->>'token'],'[]')) h where (h->>'source')::int=a and data->'targets' @> jsonb_build_array(h->'target');s:=jsonb_set(s,'{stage3,f,results}',(s#>'{stage3,f,results}')-(data->>'token'));if ml_private.stage4_on_board(s,a) then s:=ml_private.heal(s,a,amount);end if;return s;end if;
 if action in ('f-drift','f-home') then if not ml_private.stage4_on_board(s,a) then return s;end if;
  if action='f-drift' then cell:=ml_private.stage3_direction_cell(s#>>array['players',a::text,'cell'],'right');if cell is null or not ml_private.stage4_board_empty(s,a,cell,jsonb_build_array(a)) then return s;end if;
  else select coalesce(jsonb_agg(v->'id' order by ord),'[]') into cells from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality q(v,ord) where v->>'region'=ml_private.version_catalog(s->>'version')#>>array['sourceCatalog','characters',s#>>array['players',a::text,'character'],'spawnRegion'] and ml_private.stage4_board_empty(s,a,v->>'id',jsonb_build_array(a));if jsonb_array_length(cells)=0 then return s;end if;s:=ml_private.int(s,jsonb_array_length(cells));cell:=cells->>(s->>'_int')::int;s:=s-'_int';end if;
  s:=ml_private.p3e_relocate(s,a,cell,false,true,true,a,data->>'root');return ml_private.stage3_prepend(s,s->'_relocationTasks')-'_relocationTasks';end if;
 if action='f-self-harm' then if ml_private.stage4_on_board(s,a) and c->'serial'=t->'serial' and c->>'countered'='false' and not(c->'cancelled' @> jsonb_build_array(a)) then s:=ml_private.select_choice(s,'f-self-harm',a,at,jsonb_build_object('data',jsonb_build_object('serial',t->'serial')));end if;return s;end if;
 if action in ('f-bccb','f-sting') then region:=data->>'region';if ml_private.stage4_on_board(s,a) and ml_private.p3f_allowed(s,a,target) and ml_private.game_data(s,'map')#>>array[s#>>array['players',a::text,'cell'],'region']=region and ml_private.game_data(s,'map')#>>array[s#>>array['players',target::text,'cell'],'region']=region then s:=ml_private.select_choice(s,action,a,at,jsonb_build_object('source',target,'data',data));end if;return s;end if;
 if action='f-discard' then amount:=least((data->>'count')::int,jsonb_array_length(s#>array['players',target::text,'hand']));if ml_private.p3f_allowed(s,a,target) and amount>0 then s:=ml_private.select_choice(s,'f-discard',target,at,jsonb_build_object('source',a,'count',amount,'cards',s#>array['players',target::text,'hand']));end if;return s;end if;
 raise exception '未知F批任务';end $$;
create or replace function ml_private.p3f_choose(s jsonb,cmd jsonb,at double precision,timeout boolean) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare c jsonb:=s->'choice';a integer:=(c->>'actor')::int;k text:=c->>'kind';d jsonb:=c->'data';n integer;rolln integer;target integer;targets jsonb;cards jsonb;card text;idx integer;pending jsonb:=s#>'{cardStack,stack,-1}';jobs jsonb:='[]';begin
 if k='f-tenacity' then perform ml_private.need(timeout or coalesce(cmd->>'option','0')~'^(0|[1-9][0-9]*)$','坚韧抵挡数量无效');n:=case when timeout then 0 else coalesce(cmd->>'option','0')::int end;perform ml_private.need(n>=0 and n<=(c->>'count')::int and n<(s#>>array['players',a::text,'maxHp'])::int,'坚韧抵挡数量无效');s:=jsonb_set(s,array['players',a::text,'maxHp'],to_jsonb((s#>>array['players',a::text,'maxHp'])::int-n));s:=jsonb_set(s,array['players',a::text,'hp'],to_jsonb(least((s#>>array['players',a::text,'hp'])::int,(s#>>array['players',a::text,'maxHp'])::int)));d:=jsonb_set(d,'{prepared,remaining}',to_jsonb((d#>>'{prepared,remaining}')::int-n));s:=ml_private.emit(s,'skill','S'||(a+1)||' 坚韧：消耗'||n||'上限抵挡'||n||'伤害');return ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('f-damage',jsonb_build_object('data',d))));end if;
 if k='f-discard' then if timeout then select coalesce(jsonb_agg(v order by v#>>'{}'),'[]') into cards from (select v from ml_private.arr(s#>array['players',a::text,'hand']) v order by v#>>'{}' limit (c->>'count')::int) q;else cards:=coalesce(cmd->'cards','[]');end if;perform ml_private.need(jsonb_array_length(cards)=(c->>'count')::int and (select count(distinct v) from ml_private.arr(cards) v)=jsonb_array_length(cards) and not exists(select 1 from ml_private.arr(cards) v where not(c->'cards' @> jsonb_build_array(v)) or not(s#>array['players',a::text,'hand'] @> jsonb_build_array(v))),'F技能弃牌不合法');for card in select v#>>'{}' from ml_private.arr(cards) v loop s:=jsonb_set(s,array['players',a::text,'hand'],(s#>array['players',a::text,'hand'])-card);end loop;s:=ml_private.exercise_discard(s,cards);return ml_private.emit(s,'discard','S'||(a+1)||' F技能弃置'||jsonb_array_length(cards)||'张');end if;
 if k='f-target' then targets:=ml_private.p3f_targets(s,a);target:=case when timeout then (targets->>0)::int else (cmd->>'target')::int end;perform ml_private.need(target is not null and c->'targets' @> jsonb_build_array(target) and targets @> jsonb_build_array(target),'自虐伤害目标不合法');s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','response')));return ml_private.stage3_prepend(s,s->'_triggers')-'_triggers';end if;
 if timeout or not coalesce((cmd->>'accept')::boolean,false) or not ml_private.stage4_on_board(s,a) then return s;end if;s:=ml_private.die(s,case when k='f-self-harm' then '自虐' when k='f-bccb' then 'bccb' else '毒蜇' end);rolln:=(s->>'_roll')::int;s:=s-'_roll';
 if k='f-self-harm' then perform ml_private.need(pending->'serial'=d->'serial','自虐卡牌已过期');if rolln<=2 then return s;end if;if not(pending->'cancelled' @> jsonb_build_array(a)) then s:=jsonb_set(s,array['cardStack','stack',(jsonb_array_length(s#>'{cardStack,stack}')-1)::text,'cancelled'],(pending->'cancelled')||jsonb_build_array(a));end if;
  if rolln<=5 then for target in select (v#>>'{}')::int from ml_private.arr(s->'order') v where (v#>>'{}')::int<>a and s#>array['players',v#>>'{}','team']<>s#>array['players',a::text,'team'] and ml_private.p3f_allowed(s,a,(v#>>'{}')::int,true) loop jobs:=jobs||jsonb_build_array(ml_private.stage3_task('f-discard',jsonb_build_object('actor',a,'target',target,'data',jsonb_build_object('count',1))));end loop;return ml_private.stage3_prepend(s,jobs);
  else targets:=ml_private.p3f_targets(s,a);if jsonb_array_length(targets)>0 then s:=ml_private.select_choice(s,'f-target',a,at,jsonb_build_object('targets',targets));end if;return s;end if;end if;
 target:=(c->>'source')::int;if not ml_private.p3f_allowed(s,a,target) then return s;end if;
 if k='f-sting' then if rolln<=3 then return ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('f-discard',jsonb_build_object('actor',a,'target',target,'data',jsonb_build_object('count',2)))));elsif rolln<=5 then s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',2,'source',a,'category','response')));return ml_private.stage3_prepend(s,s->'_triggers')-'_triggers';else return s;end if;end if;
 if rolln<=4 then for n in 1..2 loop cards:=s#>array['players',target::text,'hand'];exit when jsonb_array_length(cards)=0;s:=ml_private.int(s,jsonb_array_length(cards));idx:=(s->>'_int')::int;s:=s-'_int';card:=cards->>idx;s:=jsonb_set(s,array['players',target::text,'hand'],cards-idx);s:=jsonb_set(s,array['players',a::text,'hand'],(s#>array['players',a::text,'hand'])||jsonb_build_array(card));end loop;jobs:=jsonb_build_array(jsonb_build_object('target',a,'amount',1,'source',a,'category','response'));
 else jobs:=jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','response'),jsonb_build_object('target',a,'amount',1,'source',a,'category','response'));end if;s:=ml_private.damage(s,jobs);return ml_private.stage3_prepend(s,s->'_triggers')-'_triggers';end $$;
